SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.diagnosis_code, COUNT(DISTINCT a.hadm_id) AS n, AVG(m.complexity_score) AS avg_complexity_score, AVG(a.length_of_stay) AS avg_length_of_stay, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_count, SUM(CASE WHEN r.hadm_id IS NOT NULL THEN 1 ELSE 0 END) AS readmission_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id JOIN (SELECT hadm_id, complexity_score FROM emar_detail) m ON a.hadm_id = m.hadm_id LEFT JOIN (SELECT hadm_id, subject_id FROM transfers) t ON a.hadm_id = t.hadm_id LEFT JOIN (SELECT hadm_id, subject_id FROM services) s ON a.hadm_id = s.hadm_id LEFT JOIN (SELECT hadm_id, subject_id FROM icustays) i ON a.hadm_id = i.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 43 AND 53 AND d.diagnosis_code = '426' AND a.admittime BETWEEN 0 AND 7 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.diagnosis_code ORDER BY n DESC, avg_complexity_score DESC, avg_length_of_stay DESC, mortality_count DESC, readmission_count DESC;